{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol, a lipophilic isoprenoid with a polar chromanol head and unsaturated prenyl tail, has poor oral bioavailability in humans, supporting low absorption for the structurally analogous ubiquinone-type polyprenyl quinone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lycopene, a highly lipophilic long-chain isoprenoid, showed only about 1.2% systemic availability from an oil-dispersed dose in humans, indicating that large lipophilic isoprenoid molecules can have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a long-chain isoprenoid carotenoid, was estimated to have 58.5% bioavailability in humans, providing a counterexample that some highly lipophilic isoprenoids can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a polyprenylated lipophilic natural product, showed high oral bioavailability in volunteers, another counterexample that prenylated lipophilic molecules are not inherently poorly absorbed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a coenzyme-Q-type polyprenyl benzoquinone. The closest structural/biological analog among the evidence is tocotrienol, which has poor oral bioavailability, and the general behavior of large lipophilic coenzyme Q molecules is poor absorption. Although phytoene and hyperforin show that some lipophilic isoprenoids can be well absorbed, the quinone/polar-head plus long polyprenyl-tail architecture and known coenzyme Q absorption behavior favor F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for ubiquinone-9 or a closely matching coenzyme Q analog is present.",
    "Most lycopene records are systemic availability from food matrices rather than true absolute bioavailability, limiting quantitative transfer.",
    "The tocotrienol evidence is qualitative ('poor') and does not provide a precise F value against the 20% threshold."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tocotrienol"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lycopene"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C02"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "phytoene"
    },
    {
      "applicability": "low",
      "card_ids": ["C10"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "hyperforin"
    }
  ],
  "revision_action": "initial"
}

